        }
      },
      {
        "item": "viz_18",
        "type": "block",
        "position": {
          "x": 720,
          "y": 1688,
          "w": 720,
          "h": 384
        }
      }
    ],
    "globalInputs": [
      "input_global_trp"
    ]
  }
}
